import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(11))
G.add_edges_from([(1,10), (0,4), (0,8), (2,9)])
# Add edges to ensure every vertex has degree at least 3
for i in range(11):
    if G.degree(i) < 3:
        for j in range(i+1, 11):
            if G.degree(j) < 3 and not G.has_edge(i, j):
                G.add_edge(i, j)
                break
# Check if the maximum clique size is at most 4
max_clique_size = 0
for clique in nx.find_cliques(G):
    max_clique_size = max(max_clique_size, len(clique))
if max_clique_size > 4:
    print("UNSATISFIABLE")
else:
    # Check if the chromatic number is at most 2
    coloring = nx.greedy_color(G)
    if max(coloring.values()) > 1:
        print("UNSATISFIABLE")
    else:
        print("SATISFIABLE")
        print(list(G.edges))
